async function adminCampal(player) {
  await menu(player, "§l§aCAMPAL", `§7Dentro: §f${campalPlayers().map((p) => p.name).join(", ") || "nadie"}\n `, [
    ["§f§lAJUSTES", async () => {
      if (await settingsForm(player, "campal", "Campal", [
        ["enabled", "toggle", "§fArena abierta"],
        ["reward", "toggle", "§fPremio por baja (regeneración + manzana dorada)"],
        ["spawnProtection", "slider", "§fProtección al aparecer (segundos)", 0, 10, 1],
        ["combatTag", "slider", "§fSegundos sin recibir daño para poder salir", 0, 30, 1],
        ["sidebar", "toggle", "§fMostrar la tabla de bajas a la derecha"],
      ])) {
        campalSidebar();
        if (!S.campal.enabled) for (const p of campalPlayers()) sendToLobby(p, "§a[Campal]§r La arena se ha cerrado.");
      }
    }, "textures/ui/settings_glyph_color_2x"],
    ["§f§lREINICIAR LA TABLA DE BAJAS", () => {
      try {
        world.scoreboard.removeObjective(OBJ);
      } catch {}
      campalSidebar();
      for (const p of campalPlayers()) campalObjective().setScore(p, 0);
      player.sendMessage("§a[Admin] Tabla de bajas reiniciada.");
    }, "textures/ui/refresh_light"],
    ["§f§lENVIAR A TODOS AL LOBBY", () => {
      for (const p of campalPlayers()) sendToLobby(p, "§a[Campal]§r Un administrador te envió al lobby.");
    }, "textures/ui/arrow_left"],
  ], () => openAdmin(player));
}

async function adminKits(player) {
  await menu(player, "§l§dKITS", "§7Elige un kit para verlo, probarlo o cambiarlo por tu inventario.\n ", KIT_IDS.map((id) => [
    `§f§l${DEFAULT_KITS[id].name.toUpperCase()}\n§r§8${getKit(id).custom ? "personalizado" : "por defecto"}`, () => adminKit(player, id), "textures/items/diamond_chestplate",
  ]), () => openAdmin(player));
}

async function adminKit(player, id) {
  const kit = getKit(id);
  const extra = id === "hunted" ? "\n§eEs el kit base: con 2, 3 y 4 cazadores sube de nivel (protección, filo, poder, más manzanas, telarañas y perlas, velocidad y vida extra).\n" : "";
  await menu(player, `§l${kit.name}`, `§7${kit.desc}\n${extra}\n${describeKit(kit)}\n `, [
    ["§f§lPROBARLO\n§r§8en el modo libre", () => {
      if (st(player).mode !== "free") toggleFree(player);
      giveKit(player, id === "hunted" ? scaledHuntedKit(1) : kit);
      player.getComponent("minecraft:inventory")?.container?.setItem(8, ITEMS.admin());
    }, "textures/items/diamond_sword"],
    ["§f§lGUARDAR MI INVENTARIO COMO ESTE KIT", async () => {
      if (!(await confirm(player, "Guardar kit", `Tu inventario y armadura actuales serán el kit "${kit.name}".`))) return;
      try {
        const n = saveKitFrom(player, id);
        player.sendMessage(n ? `§a[Admin] Kit "${kit.name}" guardado (${n} objetos).` : "§c[Admin] Tu inventario está vacío.");
      } catch (e) {
        player.sendMessage(`§c[Admin] ${e.message ?? e}`);
      }
    }, "textures/ui/confirm"],
    ["§f§lRESTAURAR EL DE POR DEFECTO", () => {
      resetKit(id);
      player.sendMessage(`§a[Admin] Kit "${kit.name}" restaurado.`);
    }, "textures/ui/refresh_light"],
  ], () => adminKits(player));
}

async function adminWorld(player) {
  const form = new ui.ModalFormData().title("Mundo")
    .dropdown("§fHora del día", TIMES.map((t) => t[0]), { defaultValueIndex: S.world.time })
    .toggle("§fCongelar la hora (no pasa el tiempo)", { defaultValue: S.world.lockTime })
    .toggle("§fRegeneración natural de vida", { defaultValue: S.world.naturalRegen })
    .textField("§fAnuncio para todos (opcional, sale en pantalla)", "escribe un anuncio", { defaultValue: "" })
    .submitButton("§a§lAplicar");
  const r = await showForm(player, form);
  if (!r || r.canceled || !r.formValues) return;
  const [time, lockTime, naturalRegen, msg] = r.formValues;
  Object.assign(S.world, { time, lockTime, naturalRegen });
  saveSettings();
  applyWorld();
  if (typeof msg === "string" && msg.trim()) {
    world.sendMessage(`§6[Anuncio]§r ${msg.trim()}`);
    for (const p of world.getPlayers()) title(p, "§6§lANUNCIO", `§f${msg.trim()}`, 60);
  }
  player.sendMessage("§a[Admin] Mundo actualizado. (El clima está desactivado: nunca llueve.)");
}

async function adminPlayers(player) {
  const list = world.getPlayers();
  const modeName = { lobby: "lobby", duel: "duelo", hunt: "caza", hunt_spec: "espectador (caza)", spec: "espectador", campal: "campal", free: "modo libre" };
  await menu(player, "§l§6JUGADORES", "§7Elige un jugador.\n ", list.map((p) => [
    `${isAdmin(p) ? "§c" : "§f"}§l${p.name}\n§r§8${modeName[st(p).mode] ?? st(p).mode}${isAdmin(p) ? " · admin" : ""}`, () => adminPlayer(player, p), "textures/items/name_tag",
  ]), () => openAdmin(player));
}

async function adminPlayer(player, target) {
  if (!valid(target)) return;
  const admin = isAdmin(target);
  await menu(player, `§l${target.name}`, `§7Modo: §f${st(target).mode}\n§7Admin: §f${admin ? "sí" : "no"}\n `, [
    ["§f§lENVIAR AL LOBBY\n§r§8lo saca de la partida o la cola", () => removeFromGame(target, `§e[Admin]§r ${player.name} te envió al lobby.`), "textures/ui/arrow_left"],
    [admin ? "§c§lQUITAR ADMIN" : "§a§lDAR ADMIN", () => {
      if (admin) target.removeTag(ADMIN_TAG);
      else target.addTag(ADMIN_TAG);
      player.sendMessage(`§a[Admin] ${target.name} ${admin ? "ya no es" : "ahora es"} administrador.`);
      target.sendMessage(admin ? "§7Ya no eres administrador." : "§aAhora eres administrador: usa el reloj o /natura:admin.");
    }, "textures/items/clock_item"],
    ["§f§lCURAR", () => heal(target), "textures/items/apple_golden"],
    ["§f§lVER SUS ESTADÍSTICAS", () => openStats(player, target.name), "textures/items/book_normal"],
    ["§f§lIR HACIA ÉL\n§r§8en modo libre", () => {
      if (st(player).mode !== "free") toggleFree(player);
      tp(player, target.location);
    }, "textures/items/ender_pearl"],
    ["§f§lQUE SEA EL PRÓXIMO CAZADO", () => {
      hunt.nextHunted = target.id;
      player.sendMessage(`§a[Admin] ${target.name} será el próximo cazado si está en la cola.`);
    }, "textures/items/bow_standby"],
    ["§c§lREINICIAR SUS ESTADÍSTICAS", async () => {
      if (!(await confirm(player, "Reiniciar estadísticas", `Se borran las estadísticas de ${target.name}.`))) return;
      delete STATS[target.name];
      statsDirty = true;
    }, "textures/ui/trash"],
  ], () => adminPlayers(player));
}

function removeFromGame(target, message) {
  const s = st(target);
  leaveQueues(target);
  if (s.mode === "duel" && s.match) {
    const m = s.match;
    endDuel(m, 1 - m.ids.indexOf(target.id), "un administrador sacó a un jugador");
  } else if (s.mode === "hunt") huntEliminate(target.id, undefined, "fue retirado por un administrador");
  hunt.spectators.delete(target.id);
  sendToLobby(target, message);
}

function toggleFree(player) {
  const s = st(player);
  if (s.mode === "free") return sendToLobby(player, "§7Saliste del modo libre.");
  removeFromGame(player);
  s.mode = "free";
  clearPlayer(player);
  clearEffects(player);
  setMode(player, GM.creative);
  player.getComponent("minecraft:inventory")?.container?.setItem(8, ITEMS.admin());
  player.sendMessage("§2[Admin]§r Modo libre: creativo y sin límites del mapa, con el §creloj§r del panel a mano. Para salir: panel → Salir del modo libre, o /natura:lobby.");
}

async function adminTeleport(player) {
  const go = (loc) => {
    if (st(player).mode !== "free") toggleFree(player);
    tp(player, loc);
  };
  await menu(player, "§l§3IR A UNA ZONA", "§7Te pone en modo libre (creativo) para moverte por el mapa.\n ", [
    ["§f§lLOBBY", () => sendToLobby(player), "textures/blocks/sapling_oak"],
    ["§f§lSALA DE LA VICTORIA", () => go({ x: VICTORY.start.x, y: VICTORY.start.y + 2, z: VICTORY.start.z }), "textures/items/totem"],
    ...DUELS.map((d) => [`§b§l${d.name}\n§r§8Emparejamiento`, () => go({ x: d.cx + 0.5, y: DUEL.y + 6, z: d.cz + 0.5 }), "textures/items/diamond_sword"]),
    ["§a§lCAMPAL", () => go({ x: CAMPAL.cx + 0.5, y: CAMPAL.y + 8, z: CAMPAL.cz + 0.5 }), "textures/items/iron_sword"],
    ...HUNTS.map((m) => [`§c§l${m.name}\n§r§8Caza`, () => go({ x: m.cx + 0.5, y: m.surface(m.cx, m.cz).y + 25, z: m.cz + 0.5 }), "textures/items/bow_standby"]),
  ], () => openAdmin(player));
}

async function adminMore(player) {
  await menu(player, "§l§8MÁS", "", [
    ["§f§lRECONSTRUIR UNA ZONA\n§r§8la deja como al principio", () => adminRebuild(player), "textures/blocks/grass_side_carried"],
    ["§c§lREINICIAR TODAS LAS ESTADÍSTICAS", async () => {
      if (!(await confirm(player, "Reiniciar estadísticas", "Se borran las estadísticas de todos los jugadores ."))) return;
      STATS = {};
      statsDirty = true;
      player.sendMessage("§a[Admin] Estadísticas reiniciadas.");
    }, "textures/ui/trash"],
    ["§c§lAJUSTES POR DEFECTO\n§r§8modos, tiempos y mundo", async () => {
      if (!(await confirm(player, "Ajustes por defecto", "Los modos, tiempos, mapas y el mundo vuelven a los valores iniciales (los kits no)."))) return;
      S = clone(DEFAULTS);
      saveSettings();
      applyWorld();
      campalSidebar();
      player.sendMessage("§a[Admin] Ajustes restaurados.");
    }, "textures/ui/refresh_light"],
  ], () => openAdmin(player));
}

async function adminRebuild(player) {
  await menu(player, "§l§4RECONSTRUIR", "§7Vuelve a colocar todos los bloques de una zona tal como era (los cambios hechos a mano se pierden). Las zonas grandes tardan un rato.\n ", AREAS.map((a) => [
    `§f${a.name}`, async () => {
      if (HUNTS.some((m) => m.id === a.id) && hunt.phase === "running" && huntMap().id === a.id) return player.sendMessage("§c[Admin] Hay una caza en ese mapa.");
      const di = DUELS.findIndex((d) => d.id === a.id);
      if (di >= 0 && duel.matches[di]) return player.sendMessage("§c[Admin] Hay un duelo en esa arena.");
      if (await confirm(player, `Reconstruir: ${a.name}`, "¿Seguro?")) rebuild(a.id);
    }, "textures/blocks/grass_side_carried",
  ]), () => adminMore(player));
}

// ------------------------------------------------------------ commands
function originPlayer(origin) {
  const e = origin?.sourceEntity ?? origin?.initiator;
  return e?.typeId === "minecraft:player" ? e : undefined;
}

system.beforeEvents.startup.subscribe((ev) => {
  const reg = ev.customCommandRegistry;
  if (!reg) return;
  const ok = (message) => ({ status: mc.CustomCommandStatus.Success, message });
  const fail = (message) => ({ status: mc.CustomCommandStatus.Failure, message });
  const any = { permissionLevel: mc.CommandPermissionLevel.Any, cheatsRequired: false };
  const register = (def, fn) => {
    try {
      reg.registerCommand(def, fn);
    } catch (e) {
      console.warn(`[Natura PvP] comando ${def.name}: ${e}`);
    }
  };
  register({ ...any, name: "natura:menu", description: "Abre el menú de Natura PvP" }, (origin) => {
    const p = originPlayer(origin);
    if (!p) return fail("Solo jugadores.");
    system.run(() => openSelector(p));
    return ok();
  });
  register({ ...any, name: "natura:lobby", description: "Vuelve al lobby (o sal de la cola o deja de espectar)" }, (origin) => {
    const p = originPlayer(origin);
    if (!p) return fail("Solo jugadores.");
    system.run(() => {
      const s = st(p);
      if (s.mode === "campal") campalLeave(p);
      else if (s.mode === "hunt_spec" || s.mode === "free" || s.mode === "spec") {
        hunt.spectators.delete(p.id);
        sendToLobby(p);
      } else if (s.mode === "lobby") {
        leaveQueues(p);
        sendToLobby(p, "§7Estás en el lobby (y fuera de las colas).");
      } else p.sendMessage("§cNo puedes salir en mitad de una partida.");
    });
    return ok();
  });
  register({ ...any, name: "natura:admin", description: "Abre el panel de administración (etiqueta admin)" }, (origin) => {
    const p = originPlayer(origin);
    if (!p) return fail("Solo jugadores.");
    system.run(() => openAdmin(p));
    return ok();
  });
  register({
    permissionLevel: mc.CommandPermissionLevel.GameDirectors, cheatsRequired: false, name: "natura:hacer_admin",
    description: "Da la etiqueta admin de Natura PvP", mandatoryParameters: [{ type: mc.CustomCommandParamType.PlayerSelector, name: "jugadores" }],
  }, (origin, players) => {
    system.run(() => {
      for (const p of players ?? []) {
        p.addTag(ADMIN_TAG);
        p.sendMessage("§aAhora eres administrador de Natura PvP: usa el reloj o /natura:admin.");
      }
    });
    return ok(`Admin dado a ${players?.length ?? 0} jugador(es).`);
  });
  register({
    permissionLevel: mc.CommandPermissionLevel.GameDirectors, cheatsRequired: false, name: "natura:quitar_admin",
    description: "Quita la etiqueta admin de Natura PvP", mandatoryParameters: [{ type: mc.CustomCommandParamType.PlayerSelector, name: "jugadores" }],
  }, (origin, players) => {
    system.run(() => {
      for (const p of players ?? []) p.removeTag(ADMIN_TAG);
    });
    return ok(`Admin quitado a ${players?.length ?? 0} jugador(es).`);
  });
});
